import{_ as t,o,c as n,ag as a}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/collaborate/share-dialog.png",i="/docs/images/collaborate/share-recipient-view.png",k=JSON.parse('{"title":"Share a document","description":"Create a share link so people outside your workspace can view or edit a document, and copy or revoke links later.","frontmatter":{"title":"Share a document","description":"Create a share link so people outside your workspace can view or edit a document, and copy or revoke links later.","type":"how-to"},"headers":[],"relativePath":"collaborate/share.md","filePath":"collaborate/share.md"}'),s={name:"collaborate/share.md"};function l(h,e,d,c,p,g){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="share-a-document" tabindex="-1">Share a document <a class="header-anchor" href="#share-a-document" aria-label="Permalink to &quot;Share a document&quot;">​</a></h1><p>Create a share link to let anyone open a document in their browser, with or without a Wafflebase account.</p><p>A share link works for every document type: sheets, docs, presentations, notes, boards, PDFs, images, and other files. Members of your workspace don&#39;t need a link; they can already open everything in it.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Any member can create a <strong>Viewer</strong> link.</li><li>An <strong>Editor</strong> link needs the document&#39;s author or a workspace owner.</li><li>A link never expires unless you pick an <strong>Expiration</strong>.</li></ul></div><h2 id="create-a-share-link" tabindex="-1">Create a share link <a class="header-anchor" href="#create-a-share-link" aria-label="Permalink to &quot;Create a share link&quot;">​</a></h2><ol><li>Open the document.</li><li>Click <strong>Share</strong> in the top right of the header.</li><li>Under <strong>Permission</strong>, select <strong>Viewer</strong> or <strong>Editor</strong>.</li><li>Under <strong>Expiration</strong>, select <strong>No limit</strong>, <strong>1 hour</strong>, <strong>8 hours</strong>, <strong>24 hours</strong>, or <strong>7 days</strong>.</li><li>Click <strong>Create link</strong>.</li></ol><p>The link is copied to your clipboard and appears under <strong>Active links</strong>. Paste it into an email or chat to share it.</p><p>If you can&#39;t create editor links, <strong>Editor</strong> is grayed out and the dialog says <em>Only the document owner or a workspace owner can create editor links.</em></p><div class="warning custom-block"><p class="custom-block-title">Anyone with the link can open the document</p><p>Recipients don&#39;t need to sign in, and they can pass the link on. For sensitive content, pick a short <strong>Expiration</strong> before you click <strong>Create link</strong>.</p></div><p><img src="'+r+'" alt="Share document dialog with Permission, Expiration, and two Active links"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p><strong>Share</strong> stays in the header on a phone as an icon button. Tap it to open the same dialog.</p><h2 id="copy-or-revoke-a-link" tabindex="-1">Copy or revoke a link <a class="header-anchor" href="#copy-or-revoke-a-link" aria-label="Permalink to &quot;Copy or revoke a link&quot;">​</a></h2><ol><li>Open the document and click <strong>Share</strong>.</li><li>Find the link under <strong>Active links</strong>. Each row shows its role and <strong>No expiration</strong>, a countdown such as <em>Expires in 6h</em>, or <strong>Expired</strong>.</li><li>Click the copy icon (<strong>Copy link</strong>) to copy it again, or the trash icon (<strong>Revoke link</strong>) to turn it off.</li></ol><p>A revoked link stops working right away. You can revoke links you created. The document&#39;s author and workspace owners can revoke any link. If you can&#39;t create editor links, other people&#39;s editor links aren&#39;t listed for you.</p><h2 id="choose-viewer-or-editor" tabindex="-1">Choose viewer or editor <a class="header-anchor" href="#choose-viewer-or-editor" aria-label="Permalink to &quot;Choose viewer or editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>A person with the link can</th><th>Viewer</th><th>Editor</th></tr></thead><tbody><tr><td>Open, scroll, select, and copy</td><td>Yes</td><td>Yes</td></tr><tr><td>Read comments</td><td>Yes</td><td>Yes</td></tr><tr><td>Edit, format, and undo</td><td>No</td><td>Yes</td></tr><tr><td>Add comments</td><td>No</td><td>Yes, when signed in</td></tr><tr><td>Open version history</td><td>No</td><td>No</td></tr></tbody></table><p>On a PDF, an editor link can comment without signing in.</p><h2 id="what-people-see-when-they-open-the-link" tabindex="-1">What people see when they open the link <a class="header-anchor" href="#what-people-see-when-they-open-the-link" aria-label="Permalink to &quot;What people see when they open the link&quot;">​</a></h2><ul><li>The document opens on its own, without your workspace&#39;s sidebar or documents list.</li><li>A viewer sees a <strong>View only</strong> badge next to the title. An editor sees the save status instead. See <a href="/docs/collaborate/edit-together.html#check-that-your-work-is-saved">Edit together</a>.</li><li>People who aren&#39;t signed in appear to others as <strong>Anonymous</strong>.</li><li>There is no version history. Only signed-in workspace members can see it.</li></ul><p>If the link was revoked, has expired, or the document is in the <a href="/docs/collaborate/trash.html">Trash</a>, the page says <strong>Link unavailable</strong>.</p><p><img src="'+i+'" alt="Shared doc opened without signing in, with the View only badge next to the title"></p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A link shares one document. To share many, share each one or invite people to the workspace.</li><li>Moving a document to the Trash turns off its links until it is restored. <strong>Delete forever</strong> turns them off for good.</li><li>People on a share link can&#39;t be mentioned and don&#39;t get notifications.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/workspaces.html">Workspaces and roles</a> to give someone access to everything in a workspace.</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a> to see who else is in the document.</li><li><a href="/docs/collaborate/comments.html">Comments and mentions</a> to collect feedback without edits.</li><li><a href="/docs/start/troubleshooting.html">Troubleshooting</a> if a link says <strong>Link unavailable</strong>.</li></ul>',26)])])}const m=t(s,[["render",l]]);export{k as __pageData,m as default};
